-- Correct dates for history rows generated by backend/scripts/seed_history.py.
-- Run this on the server AFTER the generator finishes. Review the verification
-- queries at the end; the whole update is one transaction.
--
-- Generated rows are marked with GT-HIST (work orders) and GT- (other tables).

BEGIN;

-- 1. Historical dates and searchable work order numbers.
UPDATE work_orders
SET number = 'НЗ-'
        || to_char(date_start, 'YYYYMMDD-HH24MISS')
        || '-'
        || left(md5(id::text), 16),
    created_at = date_start,
    updated_at = CASE
        WHEN status IN ('completed', 'cancelled')
            THEN COALESCE(date_end, date_start)
        ELSE date_start
    END,
    closed_at = CASE
        WHEN status = 'completed' THEN COALESCE(date_end, date_start)
        ELSE closed_at
    END
WHERE description LIKE 'GT-HIST-%'
  AND date_start IS NOT NULL;

-- 2. Spread mileage_history.recorded_at across the last two years.
-- The generator posts 24 monthly values per asset; the spacing adapts if a
-- run was partial (count of rows per asset is used instead of a fixed 24).
WITH ranked AS (
    SELECT mh.id,
           row_number() OVER (PARTITION BY mh.asset_id ORDER BY mh.id) AS rn,
           count(*) OVER (PARTITION BY mh.asset_id) AS cnt
    FROM mileage_history mh
    JOIN fixed_assets fa ON fa.id = mh.asset_id
    WHERE fa.inv_number LIKE 'GT-%'
      AND mh.source = 'manual'
)
UPDATE mileage_history mh
SET recorded_at = now()
    - ((r.cnt - r.rn)::int * interval '30 days' + interval '5 days')
FROM ranked r
WHERE mh.id = r.id;

COMMIT;

-- 3. Verification: expected roughly 118 000 orders across two years.
SELECT
    count(*) FILTER (WHERE status = 'completed') AS completed,
    count(*) FILTER (WHERE status = 'pending') AS pending,
    count(*) FILTER (WHERE status = 'in_progress') AS in_progress,
    count(*) FILTER (WHERE status = 'cancelled') AS cancelled,
    min(date_start) AS first_start,
    max(date_start) AS last_start,
    min(closed_at) AS first_close,
    max(closed_at) AS last_close
FROM work_orders
WHERE description LIKE 'GT-HIST-%';

SELECT
    count(*) AS mileage_rows,
    min(recorded_at) AS first_mileage,
    max(recorded_at) AS last_mileage
FROM mileage_history mh
JOIN fixed_assets fa ON fa.id = mh.asset_id
WHERE fa.inv_number LIKE 'GT-%'
  AND mh.source = 'manual';
